// UpdateMyProfile is the resolver for the updateMyProfile field.
func (r *mutationResolver) UpdateMyProfile(ctx context.Context, input model.UpdateProfileInput) (*model.UserProfile, error) {
	userID, err := requireCustomerRole(ctx)
	if err != nil {
		return nil, err
	}

	req := &userpb.UpdateUserProfileRequest{UserId: userID}

	// Build full name from first + last
	if input.FirstName != nil || input.LastName != nil {
		first := strOrEmpty(input.FirstName)
		last := strOrEmpty(input.LastName)
		if first != "" && last != "" {
			req.FullName = first + " " + last
		} else if first != "" {
			req.FullName = first
		} else if last != "" {
			req.FullName = last
		}
	}
	if input.AvatarURL != nil {
		req.AvatarUrl = *input.AvatarURL
	}
	if input.Timezone != nil {
		req.Timezone = *input.Timezone
	}
	if input.Language != nil {
		req.Language = *input.Language
	}

	_, err = r.Clients.User.UpdateUserProfile(ctx, req)
	if err != nil {
		r.Log.Error("failed to update profile", zap.Error(err), zap.String("user_id", userID))
		return nil, fmt.Errorf("failed to update profile: %w", err)
	}

	// Re-fetch profile to return updated data
	profile, err := r.Clients.User.GetUserProfile(ctx, &userpb.GetUserProfileRequest{UserId: userID})
	if err != nil {
		return nil, fmt.Errorf("failed to fetch updated profile: %w", err)
	}
	return mapUserProfileFromProto(profile), nil
}

