// MarkAllNotificationsRead is the resolver for the markAllNotificationsRead field.
func (r *mutationResolver) MarkAllNotificationsRead(ctx context.Context) (bool, error) {
	userID, err := requireCustomerRole(ctx)
	if err != nil {
		return false, err
	}

	// Fetch all unread notifications
	listResp, err := r.Clients.Notification.ListNotifications(ctx, &notifpb.ListNotificationsRequest{
		UserId: userID,
		Status: "UNREAD",
		Limit:  500,
		Offset: 0,
	})
	if err != nil {
		r.Log.Error("failed to list unread notifications", zap.Error(err), zap.String("user_id", userID))
		return false, fmt.Errorf("failed to list unread notifications: %w", err)
	}

	// Mark each as read
	for _, n := range listResp.Notifications {
		_, err := r.Clients.Notification.MarkAsRead(ctx, &notifpb.MarkAsReadRequest{
			NotificationId: n.Id,
			UserId:         userID,
		})
		if err != nil {
			r.Log.Error("failed to mark notification as read",
				zap.Error(err),
				zap.String("notification_id", n.Id),
				zap.String("user_id", userID),
			)
		}
	}

	return true, nil
}

// SendNotification is the resolver for the sendNotification field.
func (r *mutationResolver) SendNotification(ctx context.Context, input model.SendNotificationInput) (*model.Notification, error) {
	_, spID, err := requireProviderRole(ctx)
	if err != nil {
		return nil, err
	}

	priority := "NORMAL"
	if input.Priority != nil {
		priority = string(*input.Priority)
	}

	resp, err := r.Clients.Notification.CreateNotification(ctx, &notifpb.CreateNotificationRequest{
		UserId:            input.UserID,
		ServiceProviderId: spID,
		Category:          string(input.Category),
		Title:             input.Title,
		Body:              input.Body,
		Priority:          priority,
	})
	if err != nil {
		r.Log.Error("failed to send notification", zap.Error(err))
		return nil, fmt.Errorf("failed to send notification: %w", err)
	}

	return &model.Notification{
		ID:       resp.NotificationId,
		Category: input.Category,
		Title:    input.Title,
		Body:     input.Body,
		Priority: priority,
		Status:   resp.Status,
	}, nil
}

