// DashboardSummary is the resolver for the dashboardSummary field.
func (r *queryResolver) DashboardSummary(ctx context.Context) (*model.DashboardSummary, error) {
	userID, err := requireAnyAuthenticatedRole(ctx)
	if err != nil {
		return nil, err
	}

	// Fetch unread notifications by category
	personal, _ := r.Clients.Notification.ListNotifications(ctx, &notifpb.ListNotificationsRequest{
		UserId: userID, Category: "PERSONAL", Status: "UNREAD", Limit: 0, Offset: 0,
	})
	sp, _ := r.Clients.Notification.ListNotifications(ctx, &notifpb.ListNotificationsRequest{
		UserId: userID, Category: "SERVICE_PROVIDER", Status: "UNREAD", Limit: 0, Offset: 0,
	})
	ads, _ := r.Clients.Notification.ListNotifications(ctx, &notifpb.ListNotificationsRequest{
		UserId: userID, Category: "ADVERTISEMENT", Status: "UNREAD", Limit: 0, Offset: 0,
	})
	callbacks, _ := r.Clients.Communication.ListCallbackRequests(ctx, &commpb.ListCallbackRequestsRequest{
		UserId: userID, Status: "PENDING", Limit: 0, Offset: 0,
	})
	convos, _ := r.Clients.Communication.ListConversations(ctx, &commpb.ListConversationsRequest{
		UserId: userID, Limit: 0, Offset: 0,
	})

	summary := &model.DashboardSummary{}
	if personal != nil {
		summary.UnreadPersonal = int(personal.Total)
	}
	if sp != nil {
		summary.UnreadServiceProvider = int(sp.Total)
	}
	if ads != nil {
		summary.UnreadAdvertisements = int(ads.Total)
	}
	if callbacks != nil {
		summary.PendingCallbackRequests = int(callbacks.Total)
	}
	if convos != nil {
		summary.TotalConversations = int(convos.Total)
	}
	return summary, nil
}

