// MyBlockedProviders is the resolver for the myBlockedProviders field.
func (r *queryResolver) MyBlockedProviders(ctx context.Context, limit *int, offset *int) (*model.BlockedProviderConnection, error) {
	userID, err := requireCustomerRole(ctx)
	if err != nil {
		return nil, err
	}

	resp, err := r.Clients.User.ListBlockedServiceProviders(ctx, &userpb.ListBlockedServiceProvidersRequest{
		UserId: userID,
	})
	if err != nil {
		r.Log.Error("failed to list blocked providers", zap.Error(err), zap.String("user_id", userID))
		return nil, fmt.Errorf("failed to list blocked providers: %w", err)
	}

	// The proto returns a list of IDs — look up each SP
	nodes := make([]*model.BlockedProvider, 0, len(resp.ServiceProviderIds))
	for _, spID := range resp.ServiceProviderIds {
		sp, err := r.Clients.Organization.GetServiceProvider(ctx, &orgpb.GetServiceProviderRequest{
			ServiceProviderId: spID,
		})
		if err != nil {
			r.Log.Error("failed to get blocked SP details", zap.Error(err), zap.String("sp_id", spID))
			continue
		}
		nodes = append(nodes, &model.BlockedProvider{
			ServiceProvider: mapServiceProviderFromProto(sp),
			BlockedAt:       time.Now(), // Proto doesn't carry blocked_at — use current time as fallback
		})
	}

	// Apply manual pagination since the proto doesn't support it
	lim := int(intOrDefault(limit, 20))
	off := int(intOrDefault(offset, 0))
	total := len(nodes)
	if off > total {
		off = total
	}
	end := off + lim
	if end > total {
		end = total
	}

	return &model.BlockedProviderConnection{
		Nodes:      nodes[off:end],
		TotalCount: total,
	}, nil
}

// MyDashboardSummary is the resolver for the myDashboardSummary field.
func (r *queryResolver) MyDashboardSummary(ctx context.Context) (*model.CustomerDashboardSummary, error) {
	userID, err := requireCustomerRole(ctx)
	if err != nil {
		return nil, err
	}

	summary := &model.CustomerDashboardSummary{}

	// Unread notifications count
	if notifs, err := r.Clients.Notification.ListNotifications(ctx, &notifpb.ListNotificationsRequest{
		UserId: userID, Status: "UNREAD", Limit: 0, Offset: 0,
	}); err == nil {
		summary.UnreadNotifications = int(notifs.Total)
	}

	// Pending callbacks count
	if cbs, err := r.Clients.Communication.ListCallbackRequests(ctx, &commpb.ListCallbackRequestsRequest{
		UserId: userID, Status: "PENDING", Limit: 0, Offset: 0,
	}); err == nil {
		summary.PendingCallbacks = int(cbs.Total)
	}

	// Active conversations count
	if convos, err := r.Clients.Communication.ListConversations(ctx, &commpb.ListConversationsRequest{
		UserId: userID, Limit: 0, Offset: 0,
	}); err == nil {
		summary.ActiveConversations = int(convos.Total)
	}

	// Shared documents count
	if docs, err := r.Clients.Communication.ListDocumentShares(ctx, &commpb.ListDocumentSharesRequest{
		UserId: userID, Limit: 0, Offset: 0,
	}); err == nil {
		summary.SharedDocuments = int(docs.Total)
	}

	// Blocked providers count
	if blocked, err := r.Clients.User.ListBlockedServiceProviders(ctx, &userpb.ListBlockedServiceProvidersRequest{
		UserId: userID,
	}); err == nil {
		summary.BlockedProviders = len(blocked.ServiceProviderIds)
	}

	// DND active
	if dnd, err := r.Clients.User.ListDNDRules(ctx, &userpb.ListDNDRulesRequest{
		UserId: userID,
	}); err == nil {
		for _, rule := range dnd.Rules {
			if rule.IsActive {
				summary.DndActive = true
				break
			}
		}
	}

	return summary, nil
}

